function shape(points,color){c.fillStyle=color;c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.fill()}
function line(points,color,width){c.strokeStyle=color;c.lineWidth=width;c.lineCap='round';c.lineJoin='round';c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.stroke()}
function random(n){const x=Math.sin(n*127.1+dish*17.3)*43758.5453;return x-Math.floor(x)}
function plate(){ellipse(256,361,205,62,'#c0c7a5');ellipse(256,290,212,135,'#586b52');ellipse(256,282,207,128,'#d4dbcb');ellipse(256,273,192,112,'#fff9e5');ellipse(256,280,175,99,'#e7e3c9');ellipse(256,271,166,94,'#f9efd2')}
