function balls(){plate();for(let i=0;i<6;i++){const x=156+i%3*95,y=225+Math.floor(i/3)*72;ellipse(x,y+8,42,28,'#986331');ellipse(x,y,40,28,'#dbad61');if(dish===1){line([[x-28,y-12],[x+25,y+10]],'#6b412c',9);line([[x-24,y+10],[x+26,y-11]],'#f7e6c8',4)}else{line([[x-10,y-15],[x+13,y-10]],'#f2d398',4)}}if(dish===9){ellipse(395,320,38,24,'#c7d2c1');ellipse(395,315,33,17,'#bc9a55')}else garnish()}
function dessert(){plate();if(dish===25){shape([[184,282],[203,174],[308,174],[328,282]],'#edc16e');ellipse(256,282,72,30,'#e6af5b');ellipse(256,176,54,23,'#8c4c31');ellipse(250,168,43,14,'#b57648');ellipse(246,142,20,15,'#fff7db');ellipse(267,137,12,12,'#fff7db')}else if(dish===6){shape([[224,326],[204,235],[302,235],[282,326]],'#c1d3b2');ellipse(254,235,56,25,'#69884d');ellipse(255,214,47,24,'#809d5a');ellipse(257,191,35,20,'#91ab67');ellipse(259,173,23,17,'#b0c28d');ellipse(261,158,12,12,'#c7d3a5');shape([[306,241],[322,174],[339,179],[324,246]],'#d1a570')}else if(dish===26){for(let i=0;i<3;i++){const x=166+i*86;ellipse(x,260,48,35,i===1?'#efd8d3':'#fff7df');ellipse(x-7,249,32,19,i===1?'#f7e7e0':'#fffceb');if(i===2){ellipse(x+17,271,15,16,'#97655d');ellipse(x+17,271,8,9,'#c58b8e')}}}else if(dish===27){ellipse(256,277,129,49,'#754633');ellipse(256,267,129,45,'#ecd29a');ellipse(256,251,132,52,'#b77c40');ellipse(251,241,113,38,'#dba861');for(let i=0;i<30;i++)ellipse(168+random(i)*170,221+random(i+40)*41,2,2,'#ecd29a')}else if(dish===28){ellipse(256,259,135,70,'#c9a45a');ellipse(256,247,129,64,'#ead08b');for(let i=0;i<7;i++){line([[148+i*27,199],[181+i*24,297]],'#b69a53',3);line([[154,204+i*14],[354,199+i*15]],'#c0a45e',3)}}else{shape([[124,253],[173,208],[247,194],[313,208],[360,248],[395,222],[389,287],[356,270],[309,303],[223,311],[165,292]],'#b47b3e');ellipse(249,252,109,47,'#dba860');ellipse(318,231,5,5,'#775032');for(let i=0;i<6;i++)line([[187+i*22,225],[172+i*22,277]],'#b88245',3);line([[180,240],[280,276]],'#edc37c',4)}}
